    ok = ok && d->SheatheObjectAlwaysVisible && d->NeedsLoading && d->UseAnalogueLoading;
    if (!ok) { printf("004e8ce9_TEST FAIL\n"); return 1; }
    printf("004e8ce9_TEST PASS\n");
    return 0;
}

