//   CMapInfo is 72 bytes with Area (C2DBoxI) at +0.
struct C2DCoordI
{
    long x;
    long y;
    C2DCoordI() {}
    C2DCoordI(long ax, long ay) : x(ax), y(ay) {}
};

struct C2DBoxI
{
    long TLX;
    long TLY;
    long BRX;
    long BRY;
};

class CMap { };

struct CMapInfo
{
    C2DBoxI        Area;                 // +0x00
    unsigned char  _pad10[0x38];         // +0x10 .. 0x48
};

