        C2DCoordI pos = GetMapPos(i);
        if (pos.x > GetDimensions().TLX) {
            for (long y = Maps[i].Area.TLY; y < Maps[i].Area.BRY; ++y) {
                C2DCoordI outside(pos.x - 1, y);
                C2DCoordI inside(pos.x, y);
